    {
      "food": "Trà gừng",
      "reason": "Trà gừng có tính kháng viêm, giúp giảm cảm giác khó chịu và có thể giúp cải thiện giấc ngủ."
    },
    {
      "food": "Táo",
      "reason": "Táo chứa magiê, giúp giảm căng thẳng và cải thiện giấc ngủ."
